mapper.select:
SELECT COUNT(1) FROM statistics

    AND province_id = #{provinceId}
    AND city_id = #{cityId}
    AND confirm_date LIKE CONCAT('%',#{confirmDate},'%')

SELECT t.month, IFNULL(COUNT(s.id),0) AS total FROM (
SELECT #{item.month} AS month
) t LEFT JOIN statistics s ON DATE_FORMAT(s.confirm_date,'%Y-%m') = t.month GROUP BY t.month ORDER BY t.month ASC
